schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/multi-region-failover-pattern-pack.json",
  "title": "Multi-region failover pattern pack",
  "type": "object",
  "required": ["workload", "owner", "inputs", "pattern", "dns", "database", "object_store", "dependencies", "drill", "failback", "decision", "evidence", "review"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "text": {"type": "string", "minLength": 8}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "workload": {
      "type": "object",
      "required": ["name", "tier", "business_owner"],
      "additionalProperties": false,
      "properties": {
        "name": {"type": "string", "minLength": 2},
        "tier": {"type": "string", "enum": ["tier-0", "tier-1", "tier-2", "tier-3"]},
        "business_owner": {"$ref": "#/definitions/handle"}
      }
    },
    "owner": {"$ref": "#/definitions/handle"},
    "inputs": {
      "type": "array",
      "minItems": 2,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "rpo_minutes"}}}},
        {"contains": {"properties": {"name": {"const": "rto_minutes"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "value"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["rpo_minutes", "rto_minutes", "primary_region", "secondary_region"]},
          "value": {}
        },
        "allOf": [
          {"if": {"properties": {"name": {"enum": ["rpo_minutes", "rto_minutes"]}}}, "then": {"properties": {"value": {"type": "integer", "minimum": 0}}}},
          {"if": {"properties": {"name": {"enum": ["primary_region", "secondary_region"]}}}, "then": {"properties": {"value": {"type": "string", "minLength": 3}}}}
        ]
      }
    },
    "pattern": {
      "type": "object",
      "required": ["chosen", "achievable_rpo_minutes", "achievable_rto_minutes", "secondary_capacity"],
      "additionalProperties": false,
      "properties": {
        "chosen": {"type": "string", "enum": ["backup-and-restore", "pilot-light", "warm-standby", "active-passive-hot-standby", "active-active"]},
        "achievable_rpo_minutes": {"type": "integer", "minimum": 0},
        "achievable_rto_minutes": {"type": "integer", "minimum": 0},
        "secondary_capacity": {
          "type": "object",
          "required": ["mode", "percent_of_primary", "quotas_verified"],
          "additionalProperties": false,
          "properties": {
            "mode": {"type": "string", "enum": ["pre-provisioned", "scale-up"]},
            "percent_of_primary": {"type": "integer", "minimum": 0, "maximum": 200},
            "scale_up_minutes": {"type": "integer", "minimum": 0},
            "quotas_verified": {"type": "boolean", "const": true}
          },
          "if": {"properties": {"mode": {"const": "scale-up"}}},
          "then": {"required": ["scale_up_minutes"]}
        }
      }
    },
    "dns": {
      "type": "object",
      "required": ["mechanism", "ttl_ignoring_clients"],
      "additionalProperties": false,
      "properties": {
        "mechanism": {"type": "string", "enum": ["dns-failover", "global-load-balancer", "anycast", "none"]},
        "ttl_seconds": {"type": "integer", "minimum": 1, "maximum": 60},
        "health_check": {
          "type": "object",
          "required": ["endpoint", "interval_seconds", "failure_threshold"],
          "additionalProperties": false,
          "properties": {
            "endpoint": {"type": "string", "minLength": 4},
            "interval_seconds": {"type": "integer", "minimum": 1},
            "failure_threshold": {"type": "integer", "minimum": 1}
          }
        },
        "observed_propagation_seconds": {"type": "integer", "minimum": 0},
        "ttl_ignoring_clients": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["client", "fallback"],
            "additionalProperties": false,
            "properties": {
              "client": {"type": "string", "minLength": 2},
              "fallback": {"type": "string", "enum": ["global-load-balancer", "anycast", "client-side-retry-to-secondary"]}
            }
          }
        }
      },
      "if": {"properties": {"mechanism": {"const": "dns-failover"}}},
      "then": {"required": ["ttl_seconds", "health_check", "observed_propagation_seconds"]}
    },
    "database": {
      "type": "object",
      "required": ["engine", "replication", "p99_lag_seconds_30d", "promotion_procedure", "fencing", "single_writer_enforcement"],
      "additionalProperties": false,
      "properties": {
        "engine": {"type": "string", "minLength": 2},
        "replication": {"type": "string", "enum": ["synchronous", "asynchronous"]},
        "p99_lag_seconds_30d": {"type": "number", "minimum": 0},
        "promotion_procedure": {"$ref": "#/definitions/text"},
        "fencing": {"$ref": "#/definitions/text"},
        "single_writer_enforcement": {"$ref": "#/definitions/text"}
      }
    },
    "object_store": {
      "type": "object",
      "required": ["provider", "replication_enabled", "versioning", "backlog_metric", "replication_time_alert", "existing_objects_backfilled"],
      "additionalProperties": false,
      "properties": {
        "provider": {"type": "string", "minLength": 2},
        "replication_enabled": {"type": "boolean", "const": true},
        "versioning": {"type": "boolean", "const": true},
        "backlog_metric": {"type": "string", "minLength": 4},
        "replication_time_alert": {"type": "string", "minLength": 4},
        "existing_objects_backfilled": {"type": "boolean"},
        "backfill_job": {"type": "string", "minLength": 4}
      },
      "if": {"properties": {"existing_objects_backfilled": {"const": true}}},
      "then": {"required": ["backfill_job"]}
    },
    "dependencies": {
      "type": "array",
      "minItems": 3,
      "allOf": [
        {"contains": {"properties": {"kind": {"const": "identity-provider"}}}},
        {"contains": {"properties": {"kind": {"const": "dns-provider"}}}},
        {"contains": {"properties": {"kind": {"const": "ci-cd"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "kind", "reachable_from_secondary"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "minLength": 2},
          "kind": {"type": "string", "enum": ["identity-provider", "secrets-manager", "ci-cd", "dns-provider", "certificate-issuance", "payments", "email", "cloud-control-plane", "other"]},
          "reachable_from_secondary": {"type": "boolean"},
          "bypass": {"$ref": "#/definitions/text"}
        },
        "if": {"properties": {"reachable_from_secondary": {"const": false}}},
        "then": {"required": ["bypass"]}
      }
    },
    "drill": {
      "type": "object",
      "required": ["checklist", "mechanics_last_changed_at", "last"],
      "additionalProperties": false,
      "properties": {
        "checklist": {"type": "array", "minItems": 5, "items": {"$ref": "#/definitions/text"}},
        "mechanics_last_changed_at": {"$ref": "#/definitions/date"},
        "last": {
          "oneOf": [
            {"type": "null"},
            {
              "type": "object",
              "required": ["date", "scope_services", "traffic_percent", "measured_rto_minutes", "measured_rpo_minutes", "manual_steps"],
              "additionalProperties": false,
              "properties": {
                "date": {"$ref": "#/definitions/date"},
                "scope_services": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 2}},
                "traffic_percent": {"type": "number", "minimum": 0, "maximum": 100},
                "measured_rto_minutes": {"type": "number", "minimum": 0},
                "measured_rpo_minutes": {"type": "number", "minimum": 0},
                "manual_steps": {"type": "array", "items": {"$ref": "#/definitions/text"}}
              }
            }
          ]
        }
      }
    },
    "failback": {
      "type": "object",
      "required": ["trigger", "rpo_minutes", "rto_minutes", "reconciliation_step", "procedure"],
      "additionalProperties": false,
      "properties": {
        "trigger": {"$ref": "#/definitions/text"},
        "rpo_minutes": {"type": "integer", "minimum": 0},
        "rto_minutes": {"type": "integer", "minimum": 0},
        "reconciliation_step": {"$ref": "#/definitions/text"},
        "procedure": {"$ref": "#/definitions/text"}
      }
    },
    "decision": {"type": "string", "minLength": 20, "pattern": "(backup-and-restore|pilot-light|warm-standby|active-passive-hot-standby|active-active)"},
    "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "pattern": "^https://"}},
    "review": {
      "type": "object",
      "required": ["cadence", "next_review_at"],
      "additionalProperties": false,
      "properties": {
        "cadence": {"type": "string", "enum": ["monthly", "quarterly"]},
        "next_review_at": {"$ref": "#/definitions/date"}
      }
    }
  }
}

output-contract.example:
{
  "workload": {"name": "payments-api", "tier": "tier-1", "business_owner": "product:maria"},
  "owner": "arch:alice",
  "inputs": [
    {"name": "rpo_minutes", "value": 0},
    {"name": "rto_minutes", "value": 30}
  ],
  "pattern": {
    "chosen": "pilot-light",
    "achievable_rpo_minutes": 0,
    "achievable_rto_minutes": 90,
    "secondary_capacity": {"mode": "scale-up", "percent_of_primary": 10, "scale_up_minutes": 60, "quotas_verified": true}
  },
  "dns": {
    "mechanism": "dns-failover",
    "ttl_seconds": 3600,
    "health_check": {"endpoint": "https://api.payments.example.com/healthz", "interval_seconds": 30, "failure_threshold": 3},
    "observed_propagation_seconds": 0,
    "ttl_ignoring_clients": []
  },
  "database": {
    "engine": "PostgreSQL 16 (RDS)",
    "replication": "asynchronous",
    "p99_lag_seconds_30d": 40,
    "promotion_procedure": "promote the replica in the console",
    "fencing": "n/a",
    "single_writer_enforcement": "n/a"
  },
  "object_store": {
    "provider": "Amazon S3",
    "replication_enabled": true,
    "versioning": true,
    "backlog_metric": "none yet",
    "replication_time_alert": "none yet",
    "existing_objects_backfilled": false
  },
  "dependencies": [
    {"name": "Okta", "kind": "identity-provider", "reachable_from_secondary": true},
    {"name": "GitHub Actions self-hosted runners", "kind": "ci-cd", "reachable_from_secondary": false},
    {"name": "Route 53", "kind": "dns-provider", "reachable_from_secondary": true}
  ],
  "drill": {
    "checklist": [
      "announce drill window and freeze deploys",
      "promote the replica",
      "flip DNS",
      "scale up the secondary",
      "run the synthetic checkout"
    ],
    "mechanics_last_changed_at": "2026-07-14",
    "last": null
  },
  "failback": {
    "trigger": "when the primary is back",
    "rpo_minutes": 0,
    "rto_minutes": 45,
    "reconciliation_step": "to be defined",
    "procedure": "reverse the failover"
  },
  "decision": "Adopt pilot-light for payments-api with zero data loss.",
  "evidence": ["https://wiki.example.com/dr/payments-plan"],
  "review": {"cadence": "quarterly", "next_review_at": "2026-11-20"}
}
